gcp = {name:"GCP", attributes:["Often lowest compute prices","Kubernetes originator (GKE)","Strength in data/analytics (BigQuery)","Fewer regions than AWS/Azure","ML/AI via Vertex AI","Simple, resource-based pricing"]}
